import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 131 Don't be so sure!","description":"学习 may/might 的时间层次，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 131 Don't be so sure!","description":"学习 may/might 的时间层次，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 may/might 的时间层次，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 130 He can't have been ... He must have been ...","link":"/life/english/new-concept/book-1/unit-06/lesson-130"},"next":{"text":"第一册：英语初阶 · Lesson 132 He may be ... He may have been ...","link":"/life/english/new-concept/book-1/unit-06/lesson-132"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 130 He can't have been ... He must have been ...","link":"/life/english/new-concept/book-1/unit-06/lesson-130"},"next":{"text":"第一册：英语初阶 · Lesson 132 He may be ... He may have been ...","link":"/life/english/new-concept/book-1/unit-06/lesson-132"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-131.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-131.md"}`),r={name:"life/english/new-concept/book-1/unit-06/lesson-131.md"};function i(l,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-131-don-t-be-so-sure" tabindex="-1">第一册：英语初阶 · Lesson 131 Don&#39;t be so sure! <a class="header-anchor" href="#第一册-英语初阶-·-lesson-131-don-t-be-so-sure" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 131 Don&#39;t be so sure!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-132">配套课 Lesson 132</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>讨论未确定的现在与过去可能 本课要掌握may/might 的时间层次，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>probably</td><td>/ˈprɒbəbli/</td><td>adv.</td><td>很可能</td><td>probably arrive</td></tr><tr><td>perhaps</td><td>/pəˈhæps/</td><td>adv.</td><td>也许</td><td>perhaps tomorrow</td></tr><tr><td>plan</td><td>/plæn/</td><td>n.</td><td>计划</td><td>change a plan</td></tr><tr><td>possible</td><td>/ˈpɒsəbl/</td><td>adj.</td><td>可能的</td><td>a possible reason</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>may be late — 现在或将来可能迟到</li><li>may have left — 过去可能已离开</li></ul><h2 id="语法讲解-may-might-的时间层次" tabindex="-1">语法讲解：may/might 的时间层次 <a class="header-anchor" href="#语法讲解-may-might-的时间层次" aria-label="Permalink to &quot;语法讲解：may/might 的时间层次&quot;">​</a></h2><p>may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The parcel may arrive tomorrow.</p></blockquote><p>包裹可能明天到。</p><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>may not arrive 表可能不到，不是“不可能到”；不要夸大确定程度。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The parcel may arrive tomorrow.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The parcel may arrive tomorrow. Ella might have left her phone on the train.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“讨论未确定的现在与过去可能”写两至三句，再读给同伴听。至少使用一次may/might 的时间层次，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。 Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填动词原形：The parcel may ___ (arrive).</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> arrive</p><p><strong>解析：</strong> 按本课规则判断：may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“包裹可能明天到。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The parcel may arrive tomorrow.</p><p><strong>解析：</strong> May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Ella might have left her phone on the train.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 埃拉可能把手机落在火车上了。</p><p><strong>解析：</strong> Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：may/might 的时间层次。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-130">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-132">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",i]]);export{m as __pageData,b as default};
